// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address recipient, uint256 amount) public {
        vm.assume(recipient != address(c));
        amount = bound(amount, 1, address(this).balance);
        vm.deal(address(c), amount);
        uint256 balBefore = recipient.balance;
        vm.prank(c.owner());
        c.sendMoney(recipient, amount);
        assertTrue(recipient.balance == balBefore + amount && address(c).balance == 0);
    }
}
